#!/bin/bash
set -e

# ==============================================================
# kaviancrypto v7.6 Pro Terminal - Complete Zero-Km Installer
# Can be run on a brand-new server OR safely upgrade an existing one!
# Optional CLI Migration:
#   bash install_kaviancrypto_v7_6.sh /path/to/backup.zip|.json
#
# Updates in v7.6:
#   - Unified Auto Full-State Backup to Telegram (Schema v2 + SHA-256):
#       * Automatic periodic uploads enabled by default (every 4h,
#         customizable 1h-168h) once Backup Bot Token & Chat ID are set
#       * Dual Telegram Format Selector:
#           - Full Bundle (.zip): kaviancrypto_full_backup.json + all
#             readable individual files (config, trades, strategy, presets)
#           - Single Snapshot (.json): compact v2 schema
#       * Auto-Send on Change: debounced background Telegram backup
#         whenever settings, strategy code, or presets are saved
#       * Live Telegram Backup Status Dashboard in Telegram & Reports tab
#         (Payload counts, Schedule, Next Run in IRST, Last Upload, SHA-256)
#       * Unified "Send to Telegram Now" button in both Telegram & Backup tabs
# + Full-State Backup & Disaster Recovery (.zip / .json + Local Snapshots)
# + Weekly/Monthly P&L Reports + 31-Day Auto-Archive Retention
# + Split Check TP/SL Now & Visual TP/SL Report + Working Manual Exit
# + Strategy Studio Pro (Per-Strategy Parameters Menu + Presets +
#   Multi-TF Matrix + 500-Bar Walk-Forward Backtester)
# + Unified Obsidian Gold Pro Palette (Obsidian & Bento HUD)
# ==============================================================

APP_DIR="/opt/kaviancrypto"
PORT="8888"
RESTORE_ARG="${1:-}"

echo "========================================================"
echo "  kaviancrypto v7.6 Pro - Complete Zero-Km Installer"
echo "  Auto Telegram Full-State Backup (.zip / .json + SHA256)"
echo "========================================================"

echo "=== [1/6] Stopping existing service (if running) & preparing $APP_DIR ==="
systemctl stop kaviancrypto.service 2>/dev/null || true
mkdir -p "$APP_DIR" "$APP_DIR/backups"
cd "$APP_DIR"

SCRIPT_SRC="$(readlink -f "$0" 2>/dev/null || echo "$0")"
if [ -f "$SCRIPT_SRC" ] && [ "$SCRIPT_SRC" != "$APP_DIR/install_kaviancrypto_v7_6.sh" ]; then
    cp -f "$SCRIPT_SRC" "$APP_DIR/install_kaviancrypto_v7_6.sh" 2>/dev/null || true
    chmod +x "$APP_DIR/install_kaviancrypto_v7_6.sh" 2>/dev/null || true
fi

echo "=== [2/6] Installing system prerequisites ==="
apt-get update -y
apt-get install -y python3 python3-venv python3-pip curl

echo "=== [3/6] Extracting verified kaviancrypto v7.6 core files ==="
